/// How a GraphQL POST actually reaches the network.
///
/// A closure rather than a protocol so a test can inject one without any
/// conformance gymnastics: `URLSession` is not declared `Sendable` on every
/// platform, so a `Sendable` protocol it had to conform to would compile on
/// Darwin and fail on Linux.
public typealias MFETransport = @Sendable (URLRequest) async throws -> (Data, URLResponse)

/// Transport or non-2xx failure. Carries the status when there was one.
public enum MFETransportError: Error, CustomStringConvertible {
    case network(String, status: Int?)

    public var description: String {
        switch self {
        case let .network(message, status):
            return status.map { "BFF request failed (\($0)): \(message)" } ?? "BFF request failed: \(message)"
        }
    }
}

/// **The** HTTP path to a GraphQL endpoint in this package.
///
/// `doQuery` and `BFFClient` both go through here. They used to each build a
/// URLRequest, set the same headers and check the same status range, which is
/// duplication no gate could see: `check:mfe-drift` compares generated bytes to
/// the template and both stayed "correct" while free to diverge, and no test
/// exercised either path.
///
/// The web lane has that duplication for a reason this lane does not share:
/// `BaseMFE` ships in a published package and cannot import the `bff.ts`
/// generated into an MFE later. Here both files are generated into the same
/// module in the same commit.
///
/// What is NOT shared is error policy, and that difference is deliberate:
/// `doQuery` returns a `{data, errors}` envelope because that is what the
/// `query` capability answers with, and `BFFClient.query<T>` throws because a
/// caller decoding into a type should not silently receive half a response.
/// TypeScript splits them the same way.
public enum GraphQLPost {
    /// The default transport. `URLSession.shared`, in one place.
    public static let urlSession: MFETransport = { request in
        try await URLSession.shared.data(for: request)
    }

    /// POST `body` and hand back the response data, or throw.
    public static func send(
        to endpoint: URL,
        body: Data,
        headers: [String: String] = [:],
        transport: MFETransport = GraphQLPost.urlSession
    ) async throws -> Data {
        var request = URLRequest(url: endpoint)
        request.httpMethod = "POST"
        request.setValue("application/json", forHTTPHeaderField: "Content-Type")
        for (field, value) in headers {
            request.setValue(value, forHTTPHeaderField: field)
        }
        request.httpBody = body

        let data: Data
        let response: URLResponse
        do {
            (data, response) = try await transport(request)
        } catch {
            throw MFETransportError.network(error.localizedDescription, status: nil)
        }

        if let http = response as? HTTPURLResponse, !(200..<300).contains(http.statusCode) {
            throw MFETransportError.network(
                HTTPURLResponse.localizedString(forStatusCode: http.statusCode),
                status: http.statusCode
            )
        }
        return data
    }
}

