    /// and composing `manifest.endpoint` with `data.serve.endpoint`). There is
    /// no dependency container in this lane, and the composition already
    /// happened at generation time — `identity.bffEndpoint` IS
    /// `endpoint + serve.endpoint`. Same resolution, fewer steps to get there.
    open func doQuery(_ context: MFEContext) async throws -> QueryResult {
        let override =
            context.inputs["bffUrl"]?.stringValue
            ?? ProcessInfo.processInfo.environment["BFF_URL"]

        // ADR-070's uniform no-data contract.
        guard let target = override ?? identity.bffEndpoint, let url = URL(string: target) else {
            return QueryResult(data: nil, errors: [])
        }
        guard let document = context.inputs["document"]?.stringValue else {
            return QueryResult(data: nil, errors: ["context.inputs[\"document\"] is required for the query capability"])
        }

        var headers = context.headers
        if let jwt = context.jwt {
            headers["Authorization"] = "Bearer \(jwt)"
        }

        var payload: [String: JSONValue] = ["query": .string(document)]
        if let variables = context.inputs["variables"] {
            payload["variables"] = variables
        }

        let body: Data
        do {
            body = try await GraphQLPost.send(
                to: url,
                body: try JSONEncoder().encode(payload),
                headers: headers,
                transport: deps.transport ?? GraphQLPost.urlSession
            )
        } catch {
            // The envelope policy: `query` answers with errors, it does not
            // throw. `BFFClient.query<T>` throws for the same failure, which is
            // the deliberate half of the difference between the two.
            return QueryResult(data: nil, errors: [String(describing: error)])
        }

        let decoded = try JSONDecoder().decode([String: JSONValue].self, from: body)
        var errors: [String] = []
        if case let .array(list)? = decoded["errors"] {
            errors = list.compactMap { entry in
                if case let .object(fields) = entry { return fields["message"]?.stringValue }
                return nil
            }
        }
        // Partial responses carry both, and the capability returns both.
        guard let data = decoded["data"], data != .null else {
            return QueryResult(data: nil, errors: errors)
        }
        return QueryResult(data: try JSONEncoder().encode(data), errors: errors)
    }
}
